```c
#include <stdio.h>

// Function to copy 'n' bytes from 'source' to 'destination'
void memcpy_custom(void *destination, const void *source, size_t n) {
    // Cast the void pointers to char pointers for byte-wise copying
    char *dest = (char *)destination;
    const char *src = (const char *)source;

    // Copy 'n' bytes from source to destination
    for (size_t i = 0; i < n; ++i) {
        dest[i] = src[i];
    }
}

// Function to determine the length of a null-terminated string
size_t strlen_custom(const char *str) {
    const char *s;
    // Find the position of the first '\0' character in the string
    for (s = str; *s; ++s);
    return (s - str);  // Return the difference which is the length of the string
}

int main() {
    // Define a buffer large enough to hold the string "Hello" and a null-terminator
    char buffer[6];

    // The source string we want to copy into 'buffer'
    const char *source = "Hello";

    // Copy the string "Hello" into 'buffer'
    memcpy_custom(buffer, source, 5);  // Explicitly specify 5 bytes for "Hello"

    // Null-terminate the buffer
    buffer[5] = '\0';

    // Print the copied string to verify correctness
    printf("Copied String: %s\n", buffer);

    // Calculate and print the length of 'source'
    size_t source_length = strlen_custom(source);
    printf("Length of Source String: %zu\n", source_length);

    return 0;
}
```

### Explanation:

1. **`memcpy_custom`:** 
