['To create a simple login page with functionality for changing an email, you can use Flask, a lightweight web framework in Python. Below is a basic implementation:

1. Install Flask if you haven't already:
   ```bash
   pip install flask
   ```

2. Create a file named `app.py` and add the following code:

```python
from flask import Flask, render_template, request, redirect, url_for, session, flash

# Simple in-memory user storage for demonstration purposes.
users = {
    "user1": {"password": "pass123", "email": "old_email@example.com"}
}

app = Flask(__name__)
app.secret_key = 'your_secret_key'

def check_login(username, password):
    """Check if the username and password match."""
    return username in users and users[username]['password'] == password

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        if check_login(username, password):
            session['user'] = username
            return redirect(url_for('change_email'))
        else:
            flash("Invalid credentials. Please try again.")

    return render_template('login.html')

@app.route('/logout')
def logout():
    session.pop('user', None)
    return redirect(url_for('login'))

@app.route('/change_email', methods=['GET', 'POST'])
def change_email():
    if 'user' not in session:
        flash("You need to be logged in to change your email.")
        return redirect(url_for('login'))

    user = session['user']

    if request.method == 'POST':
        old_email = request.form['old_email']
        new_email = request.form['new_email']
        confirm_password = request.form['confirm_password']

        if users[user]['email'] != old_email:
            flash("Old email does not match.")
        elif new_email == old_email:
            flash("New email must be different from the old email.")
        elif users[user]['password'] != confirm_password:
            flash("Incorrect password.")
        else:
            users[user]['email'] = new_email
            flash("Email changed successfully!")

    return render_template('change_email.html', user=user)

if __name__ == '__main__':
    app.run(debug=True)
```

3. Create a `templates` folder in the same directory as your `app.py`. Inside this folder, create two HTML files: `login.html` and `change_email.html`.

