// Define the Person struct
typedef struct {
    int status;
    char *name;
} Person;

int main() {
    // Allocate memory for a new person
    Person *newPerson = (Person *)malloc(sizeof(Person));

    if (newPerson == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1; // Exit with an error code
    }

    // Set the status to 0
    newPerson->status = 0;

    // Allocate memory for the name and set it to "John"
    const char *nameToSet = "John";
    newPerson->name = (char *)malloc(strlen(nameToSet) + 1); // +1 for the null terminator

    if (newPerson->name == NULL) {
        fprintf(stderr, "Memory allocation for name failed\n");
        free(newPerson); // Free previously allocated memory
        return 1;
    }

    strcpy(newPerson->name, nameToSet);

    // Print out the person's information to verify
    printf("Status: %d\n", newPerson->status);
    printf("Name: %s\n", newPerson->name);

    // Clean up allocated memory
    free(newPerson->name);
    free(newPerson);

    return 0;
}
```

