    // O_CREAT flag to create if it doesn't exist
    // S_IRUSR | S_IWUSR sets owner's permissions to read/write
    // S_IRGRP | S_IROTH sets group and others' permissions to read-only
    fd = open(filename, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);

    if (fd == -1) {
        perror("Error opening file");
        return 1;
