```c
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>

// Function to create and execute a system command
void print_and_execute(const char *format, ...) {
    // Buffer size for the formatted string; adjust as needed.
    const int BUFFER_SIZE = 1024;
    char command[BUFFER_SIZE];

    // List of variadic arguments
    va_list args;

    // Initialize the variable argument list
    va_start(args, format);

    // Use vsnprintf to safely create a formatted string with variable arguments
    vsnprintf(command, BUFFER_SIZE, format, args);

    // End processing of the variadic arguments
    va_end(args);

    // Execute the command using system()
    int result = system(command);

    if (result == -1) {
        fprintf(stderr, "Failed to execute command.\n");
    }
}

int main() {
    // Example usage: Print and execute 'ls' with options
    print_and_execute("ls %s", "-l");

    return 0;
}
```

