    if (argc != 2) {
        fprintf(stderr, "Usage: %s <string>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Get the input string from the command line arguments
    char *input = argv[1];

    // Calculate the length of the input string
    size_t len = strlen(input);

    if (len == 0) {
        printf("\"\n");
        return EXIT_SUCCESS; 
    }

    // Trim trailing whitespace
    for (size_t i = len - 1; i != (size_t)-1; --i) {
        if (!isspace((unsigned char)input[i])) {
            input[i + 1] = '\0';
            break;
        }
    }

    // Trim newlines
    for (size_t i = strlen(input) - 1; i != (size_t)-1; --i) {
        if (input[i] == '\n') {
            input[i] = '\0';
            break;
        }
    }

    // Null-terminate the string
    printf("%s\n", input);

    return EXIT_SUCCESS;
}
```

### Explanation:

1. **Argument Check**: The program checks that exactly one argument is provided besides the program name itself using `argc`.

2. **String Validation**: It assumes that the argument is a valid C-string (null-terminated) since command-line arguments in C are passed as character arrays.

3. **Trim Trailing Whitespace**:
