#include <stdio.h>
#include <string.h>

// Function to trim trailing whitespace characters from a string
char* trim_trailing_whitespace(char *str) {
    int len = strlen(str);

    // Move the end pointer backwards until a non-whitespace character is found or start of string is reached
    while (len > 0 && (str[len - 1] == ' ' || str[len - 1] == '\t' || str[len - 1] == '\n')) {
        len--;
    }

    // Set the new end of the string to '\0'
    if (len < strlen(str)) {
        str[len] = '\0';
    }

    return str;
}

int main(int argc, char *argv[]) {
    // Check if a command-line argument is provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <argument>\n", argv[0]);
        return 1;
    }

    // Trim trailing whitespace and print the result
    printf("Original input: '%s'\n", argv[1]);
    char *trimmed = trim_trailing_whitespace(argv[1]);
    printf("Trimmed input: '%s'\n", trimmed);

    return 0;
}
